#' @title S3 Methods: print
#'
#' @description
#' Provides user-friendly, formatted console output for objects generated by
#' the \pkg{ForceChoice} package. This generic function dispatches to
#' class-specific methods that display concise summaries of fitted models,
#' simulation datasets, goodness-of-fit indices, and rotated solutions.
#' Designed for interactive use and quick diagnostic inspection.
#'
#' @param x An object of one of the following classes:
#'   \itemize{
#'     \item Fitted model objects: \code{\link[ForceChoice]{fit.MIRT}}
#'       (\code{"MIRT"}), \code{\link[ForceChoice]{fit.MGPCM}}
#'       (\code{"MGPCM"}), \code{\link[ForceChoice]{fit.MGGUM}}
#'       (\code{"MGGUM"}), \code{\link[ForceChoice]{fit.FCMIRT}}
#'       (\code{"FCMIRT"}), \code{\link[ForceChoice]{fit.FCDCM}}
#'       (\code{"FCDCM"}), \code{\link[ForceChoice]{fit.FCGGUM}}
#'       (\code{"FCGGUM"}), \code{\link[ForceChoice]{fit.TIRT}}
#'       (\code{"TIRT"})
#'     \item Goodness-of-fit objects: \code{\link[ForceChoice]{good.of.fit}}
#'       (\code{"good.of.fit"})
#'     \item Summary objects: \code{summary.MIRT}, \code{summary.MGPCM},
#'       \code{summary.MGGUM}, \code{summary.FCMIRT}, \code{summary.FCDCM},
#'       \code{summary.FCGGUM}, \code{summary.TIRT},
#'       \code{summary.good.of.fit}
#'   }
#' @param ... Additional arguments passed to methods (currently ignored in
#'   most cases).
#' @param digits Number of decimal places for numeric output (default: 4).
#'   Used by \code{print.good.of.fit}.
#'
#' @return Invisibly returns the input object \code{x}. No data is modified.
#'
#' @details
#' Each method produces a structured, human-readable summary optimized for
#' its object type:
#'
#' \describe{
#'   \item{\strong{Fitted Model Objects}}{
#'     Invokes \code{summary()} internally and prints comprehensive output
#'     including:
#'     \itemize{
#'       \item Model call and configuration (family, method, dimensions)
#'       \item Data characteristics (N, I or B, response type)
#'       \item Fit statistics (LogLik, npar, AIC, BIC)
#'       \item Factor correlation matrix
#'       \item Person parameter summary (N x D)
#'       \item Item / statement / block parameter summary
#'       \item For FCDCM: higher-order delta parameters and classification
#'             diagnostics
#'       \item For TIRT: loading (lambda) parameter summary
#'       \item Convergence diagnostics (algorithm, batches, latent grid length L)
#'     }
#'   }
#'
#'   \item{\strong{Goodness-of-Fit Objects (\code{good.of.fit})}}{
#'     Delegates to \code{summary.good.of.fit} and prints:
#'     \itemize{
#'       \item Overview table (sample size, items, parameters, moments)
#'       \item Limited-information absolute fit (M2, RMSEA, SRMSR)
#'       \item Incremental / comparative fit (CFI, TLI, IFI)
#'       \item Likelihood and information criteria (AIC, BIC, SABIC, CAIC)
#'       \item Pseudo-\eqn{R^2} measures
#'     }
#'   }
#' }
#'
#' @section Output Conventions:
#' \itemize{
#'   \item Numeric values are rounded to the precision specified by
#'         \code{digits} (default 4).
#'   \item Parameter summary tables show Min, Q1, Median, Mean, Q3, Max
#'         across items/statements for each parameter type.
#'   \item Convergence diagnostics adapt to the estimation backend
#'         (iStEM batch diagnostics vs. Stan HMC notes).
#' }
#'
#' @name print
NULL

# ===========================================================================
# Internal display helpers
# ===========================================================================

.fc_print_header <- function(title) {
  cat("\n==============================================\n")
  cat(title, "\n", sep = "")
  cat("==============================================\n\n")
}

.fc_print_matrix <- function(mat, digits, indent = "  ") {
  if (is.null(mat) || length(mat) == 0L) return(invisible(NULL))
  m <- as.matrix(mat)
  if (nrow(m) == 0L || ncol(m) == 0L) return(invisible(NULL))
  fm <- format(round(m, digits), nsmall = digits, justify = "right")
  rn <- rownames(m)
  cn <- colnames(m)

  # ---- compute column widths for proper alignment ----
  row_label_width <- if (!is.null(rn)) max(nchar(rn), na.rm = TRUE) else 0L
  if (row_label_width < 5L) row_label_width <- 5L

  col_widths <- integer(ncol(m))
  if (!is.null(cn)) {
    col_widths <- pmax(col_widths, nchar(cn))
  }
  for (j in seq_len(ncol(m))) {
    col_widths[j] <- max(col_widths[j], max(nchar(fm[, j]), na.rm = TRUE))
  }
  # ensure minimum width of 5 per column
  col_widths <- pmax(col_widths, 5L)

  # ---- print column header ----
  if (!is.null(cn)) {
    header <- sprintf("%-*s", row_label_width, "")
    for (j in seq_len(ncol(m))) {
      header <- paste0(header, "  ", sprintf("%*s", col_widths[j], cn[j]))
    }
    cat(indent, header, "\n", sep = "")
  }

  # ---- print separator line ----
  sep_line <- paste0(indent, paste(rep(" ", row_label_width), collapse = ""))
  for (j in seq_len(ncol(m))) {
    sep_line <- paste0(sep_line, "  ", paste(rep("-", col_widths[j]), collapse = ""))
  }
  cat(sep_line, "\n", sep = "")

  # ---- print data rows ----
  for (i in seq_len(nrow(m))) {
    row_label <- if (!is.null(rn)) rn[i] else ""
    line <- sprintf("%s%-*s", indent, row_label_width, row_label)
    for (j in seq_len(ncol(m))) {
      line <- paste0(line, "  ", sprintf("%*s", col_widths[j], fm[i, j]))
    }
    cat(line, "\n", sep = "")
  }
}

.fc_print_convergence <- function(conv) {
  if (is.null(conv) || length(conv) == 0L) return(invisible(NULL))
  cat("\nConvergence:\n")
  cat(sprintf("  Algorithm: %s\n", conv$algorithm))
  if (!is.null(conv$note)) {
    cat(sprintf("  Note: %s\n", conv$note))
  }
  if (!is.null(conv$burn_in_batches)) {
    cat(sprintf("  Burn-in Batches: %s\n", conv$burn_in_batches))
  }
  if (!is.null(conv$total_batches)) {
    cat(sprintf("  Total Batches: %s\n", conv$total_batches))
  }
  if (!is.null(conv$iterations)) {
    cat(sprintf("  Iterations: %s\n", conv$iterations))
  }
  if (!is.null(conv$burnin_converged)) {
    cat(sprintf("  Burn-in Converged: %s\n", as.character(conv$burnin_converged)))
  }
  if (!is.null(conv$final_converged)) {
    cat(sprintf("  Final Converged: %s\n", as.character(conv$final_converged)))
  }
  if (!is.null(conv$final_logLik) && is.finite(conv$final_logLik)) {
    cat(sprintf("  Final LogLik: %.4f\n", conv$final_logLik))
  }
  if (!is.null(conv$final_ll_change) && is.finite(conv$final_ll_change)) {
    cat(sprintf("  Final LogLik Change: %.6f\n", conv$final_ll_change))
  }
  if (!is.null(conv$final_max_delta_change) &&
      is.finite(conv$final_max_delta_change)) {
    cat(sprintf("  Final Max Delta Change: %.6f\n",
                conv$final_max_delta_change))
  }
  if (!is.null(conv$bootstrap_R) && conv$bootstrap_R > 0L) {
    cat(sprintf("  Bootstrap SE: %s / %s successful\n",
                conv$bootstrap_successful, conv$bootstrap_R))
  }
  if (!is.null(conv$L) && is.finite(conv$L)) {
    cat(sprintf("  Theta Grid L: %d\n", as.integer(conv$L)))
  }
}

# ===========================================================================
# Model print methods
#
# Convention: print.<Class>(x, ...) delegates to
# print.summary.<Class>(summary(x, ...)). The actual formatting is in the
# print.summary.<Class> methods below.
# ===========================================================================

# ---- good.of.fit ----

#' @describeIn print Print method for \code{good.of.fit} objects.
#'   Delegates to \code{summary.good.of.fit} and prints formatted tables.
#' @export
print.good.of.fit <- function(x, digits = 4, ...) {
  summ <- summary(x, digits = digits, ...)
  print(summ, ...)
  invisible(x)
}

#' @describeIn print Print method for \code{summary.good.of.fit} objects.
#'   Displays overview, absolute-fit, comparative-fit, likelihood/IC,
#'   and pseudo-\eqn{R^2} tables.
#' @export
print.summary.good.of.fit <- function(x, ...) {
  cat("\n")
  cat("Goodness-of-Fit Summary\n")
  cat("=======================\n")

  if (is.null(x$tables)) {
    return(.gof_print_legacy_summary(x))
  }

  if (!is.null(x$tables$Overview)) {
    .gof_print_overview(x$tables$Overview)
  }

  section.labels <- c(
    Absolute_Fit_M2        = "1. Limited-information Absolute Fit",
    Comparative_Fit        = "2. Incremental / Comparative Fit",
    Likelihood_and_IC      = "3. Likelihood & Information Criteria",
    Pseudo_R2              = "4. Pseudo-R2"
  )

  for (nm in names(section.labels)) {
    tab <- x$tables[[nm]]
    if (!is.null(tab) && nrow(tab) > 0L) {
      .gof_print_metric_table(section.labels[[nm]], tab)
    }
  }

  cat("Note: guide values are descriptive heuristics, not decision rules.\n")
  invisible(x)
}

# ---- MIRT ----

#' @describeIn print Print method for \code{MIRT} objects.
#'   Multidimensional IRT (1PL--4PL) model summary.
#' @export
print.MIRT <- function(x, ...) {
  print.summary.MIRT(summary(x, ...))
  invisible(x)
}

#' @describeIn print Print method for \code{summary.MIRT} objects.
#'   Shows model config, data info, fit stats, factor correlations,
#'   person/item parameter summaries, and convergence.
#' @export
print.summary.MIRT <- function(x, ...) {
  d <- x$digits
  .fc_print_header("MULTIDIMENSIONAL IRT (MIRT) MODEL SUMMARY")

  cat("Call:\n  ", paste(deparse(x$call), collapse = "\n   "), "\n", sep = "")

  cat("\nModel Configuration:\n")
  cat(sprintf("  Family: %s\n", x$model.info$family))
  cat(sprintf("  Model: %s\n", x$model.info$model))
  cat(sprintf("  Dimensions (D): %d\n", x$model.info$D))
  cat(sprintf("  Estimation Method: %s\n", x$model.info$method))

  cat("\nData Characteristics:\n")
  cat(sprintf("  Sample Size (N): %d\n", x$data.info$N))
  cat(sprintf("  Items (I): %d\n", x$data.info$I))
  cat(sprintf("  Response Type: %s\n", x$data.info$response.type))

  cat("\nFit Statistics:\n")
  cat(sprintf("  Log-likelihood: %.*f\n", d, x$fit.stats$LogLik))
  cat(sprintf("  Free Parameters: %d\n", x$fit.stats$npar))
  cat(sprintf("  AIC: %.*f\n", d, x$fit.stats$AIC))
  cat(sprintf("  BIC: %.*f\n", d, x$fit.stats$BIC))

  if (!is.null(x$Corr)) {
    cat("\nFactor Correlation Matrix:\n")
    .fc_print_matrix(x$Corr, d)
  }

  if (!is.null(x$theta.summary)) {
    cat("\nPerson Parameter Summary (N x D):\n")
    .fc_print_matrix(x$theta.summary, d)
  }

  if (!is.null(x$par.summary)) {
    cat("\nItem Parameter Summary:\n")
    .fc_print_matrix(x$par.summary, d)
  }

  if (!is.null(x$convergence)) {
    .fc_print_convergence(x$convergence)
  }

  cat("\nUse get.fit.index() to compute goodness-of-fit indices.\n\n")
  invisible(x)
}

