# ---- FCDCM ----

#' @describeIn print Print method for \code{FCDCM} objects.
#'   Forced-Choice Diagnostic Classification Model summary with
#'   higher-order trait, attribute profiles, and classification diagnostics.
#' @export
print.FCDCM <- function(x, ...) {
  print.summary.FCDCM(summary(x, ...))
  invisible(x)
}

#' @describeIn print Print method for \code{summary.FCDCM} objects.
#'   Shows higher-order delta parameters, block eta parameters,
#'   attribute classification summary, and convergence.
#' @export
print.summary.FCDCM <- function(x, ...) {
  d <- x$digits
  .fc_print_header("FORCED-CHOICE DIAGNOSTIC CLASSIFICATION MODEL (FCDCM) SUMMARY")

  cat("Call:\n  ", paste(deparse(x$call), collapse = "\n   "), "\n", sep = "")

  cat("\nModel Configuration:\n")
  cat(sprintf("  Family: %s\n", x$model.info$family))
  cat(sprintf("  Attributes (D): %d\n", x$model.info$D))
  cat(sprintf("  DCM Type: %s\n", x$model.info$model))
  cat(sprintf("  Estimation Method: %s\n", x$model.info$method))

  cat("\nData Characteristics:\n")
  cat(sprintf("  Sample Size (N): %d\n", x$data.info$N))
  cat(sprintf("  Blocks (B): %d\n", x$data.info$B))
  cat(sprintf("  Response Type: %s\n", x$data.info$response.type))

  cat("\nFit Statistics:\n")
  cat(sprintf("  Log-likelihood: %.*f\n", d, x$fit.stats$LogLik))
  cat(sprintf("  Free Parameters: %d\n", x$fit.stats$npar))
  cat(sprintf("  AIC: %.*f\n", d, x$fit.stats$AIC))
  cat(sprintf("  BIC: %.*f\n", d, x$fit.stats$BIC))

  if (!is.null(x$delta.summary)) {
    cat("\nHigher-Order Parameters (delta):\n")
    .fc_print_matrix(x$delta.summary, d)
  }

  if (!is.null(x$par.summary)) {
    cat("\nBlock Parameters (eta):\n")
    .fc_print_matrix(x$par.summary, d)
  }

  if (!is.null(x$theta.summary)) {
    cat("\nHigher-Order Trait Summary (N x 1):\n")
    .fc_print_matrix(x$theta.summary, d)
  }

  if (!is.null(x$classification)) {
    cat("\nClassification:\n")
    cat(sprintf("  Observed Attribute Patterns: %s / %d possible\n",
                x$classification$n_patterns_observed,
                x$classification$n_patterns_possible))
    if (is.finite(x$classification$mean_max_posterior)) {
      cat(sprintf("  Mean Max Posterior: %.*f\n", d, x$classification$mean_max_posterior))
    }
  }

  if (!is.null(x$convergence)) {
    .fc_print_convergence(x$convergence)
  }

  cat("\nUse get.fit.index() to compute goodness-of-fit indices.\n\n")
  invisible(x)
}

