#' @describeIn print Print method for \code{summary.FCGDINA} objects.
#'   Shows CDM type, forced-choice block info, fit stats, delta summaries,
#'   posterior attribute probabilities, and convergence.
#' @export
print.summary.FCGDINA <- function(x, ...) {
  d <- x$digits
  .fc_print_header("FORCED-CHOICE GDINA (FCGDINA) MODEL SUMMARY")

  cat("Call:\n  ", paste(deparse(x$call), collapse = "\n   "), "\n", sep = "")

  cat("\nModel Configuration:\n")
  cat(sprintf("  Family: %s\n", x$model.info$family))
  cat(sprintf("  CDM Model: %s\n", x$model.info$model))
  cat(sprintf("  Attributes (D): %d\n", x$model.info$D))
  cat(sprintf("  Estimation Method: %s\n", x$model.info$method))
  cat(sprintf("  FC Type: %s\n", x$model.info$fc.type))

  cat("\nData Characteristics:\n")
  cat(sprintf("  Sample Size (N): %d\n", x$data.info$N))
  cat(sprintf("  Blocks (B): %d\n", x$data.info$B))
  cat(sprintf("  Total Statements (I): %d\n", x$data.info$I))
  cat(sprintf("  Response Type: %s\n", x$data.info$response.type))

  cat("\nFit Statistics:\n")
  cat(sprintf("  Log-likelihood: %.*f\n", d, x$fit.stats$LogLik))
  cat(sprintf("  Free Parameters: %d\n", x$fit.stats$npar))
  cat(sprintf("  AIC: %.*f\n", d, x$fit.stats$AIC))
  cat(sprintf("  BIC: %.*f\n", d, x$fit.stats$BIC))

  if (!is.null(x$delta.summary)) {
    cat("\nCDM Delta Parameter Summary:\n")
    .fc_print_matrix(x$delta.summary, d)
  }

  if (!is.null(x$alpha.summary)) {
    cat("\nPosterior Attribute Probability Summary (N x D):\n")
    .fc_print_matrix(x$alpha.summary, d)
  }

  if (!is.null(x$classification)) {
    cat("\nClassification:\n")
    cat(sprintf("  Observed Attribute Patterns: %s / %d possible\n",
                x$classification$n_patterns_observed,
                x$classification$n_patterns_possible))
    if (is.finite(x$classification$mean_max_posterior)) {
      cat(sprintf("  Mean Max Posterior Probability: %.*f\n",
                  d, x$classification$mean_max_posterior))
    }
  }

  if (!is.null(x$pi.stats)) {
    cat(sprintf("\nStructural Parameters (class proportions):\n"))
    cat(sprintf("  Non-zero classes: %d / %d\n",
                x$pi.stats$n_nonzero,
                x$classification$n_patterns_possible))
    cat(sprintf("  Range: [%.*f, %.*f]\n",
                d, x$pi.stats$min, d, x$pi.stats$max))
    cat(sprintf("  Entropy: %.*f\n", d, x$pi.stats$entropy))
  }

  if (!is.null(x$convergence)) {
    .fc_print_convergence(x$convergence)
  }

  cat("\nUse get.fit.index() to compute goodness-of-fit indices.\n\n")
  invisible(x)
}

# ---- FCGGUM ----

#' @describeIn print Print method for \code{FCGGUM} objects.
#'   Forced-Choice Generalized Graded Unfolding Model summary.
#' @export
print.FCGGUM <- function(x, ...) {
  print.summary.FCGGUM(summary(x, ...))
  invisible(x)
}

#' @describeIn print Print method for \code{summary.FCGGUM} objects.
#'   Shows forced-choice unfolding model config, fit stats,
#'   factor correlations, person/statement parameter summaries.
#' @export
print.summary.FCGGUM <- function(x, ...) {
  d <- x$digits
  .fc_print_header("FORCED-CHOICE GENERALIZED GRADED UNFOLDING MODEL (FCGGUM) SUMMARY")

  cat("Call:\n  ", paste(deparse(x$call), collapse = "\n   "), "\n", sep = "")

  cat("\nModel Configuration:\n")
  cat(sprintf("  Family: %s\n", x$model.info$family))
  cat(sprintf("  Dimensions (D): %d\n", x$model.info$D))
  cat(sprintf("  Estimation Method: %s\n", x$model.info$method))
  cat(sprintf("  FC Type: %s\n", x$model.info$fc.type))

  cat("\nData Characteristics:\n")
  cat(sprintf("  Sample Size (N): %d\n", x$data.info$N))
  cat(sprintf("  Blocks (B): %d\n", x$data.info$B))
  cat(sprintf("  Total Statements (I): %d\n", x$data.info$I))
  cat(sprintf("  Response Type: %s\n", x$data.info$response.type))

  cat("\nFit Statistics:\n")
  cat(sprintf("  Log-likelihood: %.*f\n", d, x$fit.stats$LogLik))
  cat(sprintf("  Free Parameters: %d\n", x$fit.stats$npar))
  cat(sprintf("  AIC: %.*f\n", d, x$fit.stats$AIC))
  cat(sprintf("  BIC: %.*f\n", d, x$fit.stats$BIC))

  if (!is.null(x$Corr)) {
    cat("\nFactor Correlation Matrix:\n")
    .fc_print_matrix(x$Corr, d)
  }

  if (!is.null(x$theta.summary)) {
    cat("\nPerson Parameter Summary (N x D):\n")
    .fc_print_matrix(x$theta.summary, d)
  }

  if (!is.null(x$par.summary)) {
    cat("\nStatement Parameter Summary:\n")
    .fc_print_matrix(x$par.summary, d)
  }

  if (!is.null(x$convergence)) {
    .fc_print_convergence(x$convergence)
  }

  cat("\nUse get.fit.index() to compute goodness-of-fit indices.\n\n")
  invisible(x)
}

