# ===========================================================================
# Internal gof table printers (used by print.summary.good.of.fit)
# ===========================================================================

.gof_print_overview <- function(tab) {
  cat("\nOverview:\n")
  width <- max(nchar(tab$Field), na.rm = TRUE)
  for (i in seq_len(nrow(tab))) {
    cat(sprintf("  %-*s  %s\n", width, tab$Field[i], tab$Value[i]))
  }
}

.gof_print_metric_table <- function(title, tab) {
  cat("\n")
  cat(title, ":\n", sep = "")

  cols <- c("Metric", "Estimate", "Recommended")
  is_sub <- grepl("^SUB:", tab$Metric, perl = TRUE)
  tab$Metric <- sub("^SUB:\\s*", "", tab$Metric, perl = TRUE)

  metric_rows <- tab[!is_sub, , drop = FALSE]
  if (nrow(metric_rows) == 0L) return(invisible(NULL))

  widths <- vapply(cols, function(col) {
    header <- if (col == "Recommended") "Guide" else col
    max(nchar(c(header, metric_rows[[col]])), na.rm = TRUE)
  }, numeric(1L))
  widths <- pmax(widths, nchar(c("Metric", "Estimate", "Guide")))

  header <- sprintf("  %-*s  %*s  %-*s",
                    widths["Metric"], "Metric",
                    widths["Estimate"], "Estimate",
                    widths["Recommended"], "Guide")
  cat(header, "\n", sep = "")
  cat("  ", paste(
    vapply(widths, function(w) paste(rep("-", w), collapse = ""), character(1L)),
    collapse = "  "
  ), "\n", sep = "")

  mi <- 1L
  for (i in seq_len(nrow(tab))) {
    if (is_sub[i]) {
      cat("\n  ", tab$Metric[i], ":\n", sep = "")
    } else {
      r <- metric_rows[mi, , drop = FALSE]
      est <- if (nchar(r$Estimate) == 0L || r$Estimate == "NA") "NA" else r$Estimate
      rec <- if (nchar(r$Recommended) == 0L) "" else r$Recommended
      cat(sprintf("  %-*s  %*s  %-*s\n",
                  widths["Metric"], r$Metric,
                  widths["Estimate"], est,
                  widths["Recommended"], rec))
      mi <- mi + 1L
    }
  }
}

.gof_print_legacy_summary <- function(x) {
  digits <- attr(x, "digits")
  if (is.null(digits)) digits <- 4

  fmt <- function(val, d = digits, int = FALSE) {
    if (is.null(val) || length(val) == 0) return(character(0))
    res <- sapply(val, function(v) {
      if (is.na(v)) return("NA")
      if (int || abs(v - round(v)) < .Machine$double.eps^0.5) {
        formatC(round(v), format = "d", big.mark = ",")
      } else {
        formatC(v, format = "f", digits = d)
      }
    })
    names(res) <- names(val)
    return(res)
  }

  print_table <- function(labels, values) {
    if (length(labels) == 0) return(invisible(NULL))
    keep <- !(is.na(values) | values == "NA")
    labels <- labels[keep]
    values <- values[keep]
    if (length(labels) == 0) return(invisible(NULL))
    width <- max(nchar(labels), na.rm = TRUE)
    for (i in seq_along(labels)) {
      cat(sprintf("  %-*s %s\n", width, labels[i], values[i]))
    }
  }

  cat(sprintf("\nSample Size (N):       %s\n", fmt(x$Sample_Size, int = TRUE)))
  cat(sprintf("Items/Indicators:      %s\n", fmt(x$Items, int = TRUE)))
  cat(sprintf("Response Type:         %s\n", x$Response_Type))
  cat(sprintf("Parameters:            %s\n", fmt(x$Parameters, int = TRUE)))
  cat(sprintf("Moments:               %s total, %s bivariate\n",
              fmt(x$Moments, int = TRUE), fmt(x$Bivariate_Moments, int = TRUE)))
  cat(sprintf("Log-Likelihood:        %s\n", fmt(x$LogLik)))
  cat(sprintf("Deviance (-2LL):       %s\n\n", fmt(x$Deviance)))

  if (length(x$IC) > 0 && !all(is.na(x$IC))) {
    cat("Information Criteria:\n")
    print_table(names(x$IC), fmt(x$IC))
    cat("\n")
  }
  invisible(x)
}


# ===========================================================================
# Simulated data print methods
# ===========================================================================

.fc_print_data_header <- function(title) {
  cat(sprintf("\n%s\n", title))
  cat(paste(rep("=", nchar(title)), collapse = ""), "\n")
}

.print_data_common <- function(x, label) {
  .fc_print_data_header(paste0("SIMULATED ", label, " DATA"))
  cat(sprintf("Sample Size (N)     : %d\n", x$N))
  cat(sprintf("Items/Indicators (I): %d\n", x$I))
  cat(sprintf("Dimensions (D)      : %d\n", x$D))
  if (!is.null(x$model)) cat(sprintf("Model               : %s\n", x$model))
  cat(sprintf("Call: %s\n", paste(deparse(x$call), collapse = " ")))
  invisible(x)
}

